use xiom.io;
module notifier {
  pub interface Notifier {
    fn notify(msg: Str);
  }

  pub fn send_alert[T: Notifier](n: &T, alert: Str) {
    n.notify(alert);
  }
}

module email_backend {
  pub type EmailNotifier = {
    address: Str;
  }

  pub fn EmailNotifier.notify(self, msg: Str) {
    io.println("Email to " + self.address + ": " + msg);
  }
}

module sms_backend {
  pub type SMSNotifier = {
    phone: Str;
  }

  pub fn SMSNotifier.notify(self, msg: Str) {
    io.println("SMS to " + self.phone + ": " + msg);
  }
}

fn main() -> Int {
  let email = email_backend.EmailNotifier{ address: "a@b.com" };
  let sms = sms_backend.SMSNotifier{ phone: "555-1234" };

  notifier.send_alert(&email, "System down!");
  notifier.send_alert(&sms, "System down!");
  return 0;
}
